import pyomo.environ as pyo

DATA = {
    "foods": ["Beef", "Pasta", "Broccoli", "Chicken", "Apple",
              "Pork", "Lentils", "Eggs", "Cheese"],
    "nutrients": ["protein", "carbs", "calories"],
    "cost": {
        "Beef": 5, "Pasta": 6, "Broccoli": 5, "Chicken": 4, "Apple": 1,
        "Pork": 6, "Lentils": 1, "Eggs": 2, "Cheese": 7,
    },
    "protein": {
        "Beef": 18, "Pasta": 2, "Broccoli": 7, "Chicken": 20, "Apple": 5,
        "Pork": 13, "Lentils": 15, "Eggs": 20, "Cheese": 9,
    },
    "carbs": {
        "Beef": 13, "Pasta": 25, "Broccoli": 30, "Chicken": 16, "Apple": 6,
        "Pork": 9, "Lentils": 18, "Eggs": 18, "Cheese": 14,
    },
    "calories": {
        "Beef": 233, "Pasta": 251, "Broccoli": 191, "Chicken": 231, "Apple": 111,
        "Pork": 275, "Lentils": 99, "Eggs": 210, "Cheese": 74,
    },
    "requirement": {
        "protein": 68,
        "carbs": 151,
        "calories": 1900,
    },
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.FOODS = pyo.Set(initialize=d["foods"])
    model.NUTRIENTS = pyo.Set(initialize=d["nutrients"])

    # Decision: amount (servings) of each food to purchase
    model.x = pyo.Var(model.FOODS, within=pyo.NonNegativeReals)

    # Objective: minimise total cost
    def obj_rule(m):
        return sum(d["cost"][i] * m.x[i] for i in m.FOODS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Nutrient content lookup per nutrient
    content = {
        "protein": d["protein"],
        "carbs": d["carbs"],
        "calories": d["calories"],
    }

    # One constraint per nutrient requirement (all "at least")
    def nutrient_rule(m, n):
        return sum(content[n][i] * m.x[i] for i in m.FOODS) >= d["requirement"][n]

    model.nutrient_req = pyo.Constraint(model.NUTRIENTS, rule=nutrient_rule)

    return model


